MinimumTripletScore::MinimumTripletScore(const TripletScoresTemp &scores,
                                             unsigned int n, std::string name)
    : TripletScore(name), scores_(scores.begin(), scores.end()), n_(n) {}

namespace {
typedef algebra::internal::MinimalSet<
    double, TripletScore *, std::less<double> > MinimumTripletScoreMS;
template <class It>
MinimumTripletScoreMS find_minimal_set_MinimumTripletScore(It b, It e,
                                                               Model *m,
                                                               const ParticleIndexTriplet& v,
                                                               unsigned int n) {
  IMP_LOG_TERSE("Finding Minimum " << n << " of " << std::distance(b, e)
                                   << std::endl);
  MinimumTripletScoreMS bestn(n);
  for (It it = b; it != e; ++it) {
    double score = (*it)->evaluate_index(m, v, nullptr);
    bestn.insert(score, *it);
  }
  return bestn;
}
}

double MinimumTripletScore::evaluate_index(Model *m, const ParticleIndexTriplet& v,
                                             DerivativeAccumulator *da) const {
  MinimumTripletScoreMS bestn = find_minimal_set_MinimumTripletScore(
      scores_.begin(), scores_.end(), m, v, n_);

  double score = 0;
  for (unsigned int i = 0; i < bestn.size(); ++i) {
    if (da) {
      bestn[i].second->evaluate_index(m, v, da);
    }
    score += bestn[i].first;
  }
  return score;
}

ModelObjectsTemp MinimumTripletScore::do_get_inputs(
    Model *m, const ParticleIndexes &pis) const {
  ModelObjectsTemp ret;
  for (unsigned int i = 0; i < scores_.size(); ++i) {
    ret += scores_[i]->get_inputs(m, pis);
  }
  return ret;
}

Restraints MinimumTripletScore::do_create_current_decomposition(
    Model *m, const ParticleIndexTriplet& vt) const {
  Restraints ret;
  MinimumTripletScoreMS bestn = find_minimal_set_MinimumTripletScore(
      scores_.begin(), scores_.end(), m, vt, n_);
  for (unsigned int i = 0; i < bestn.size(); ++i) {
    ret.push_back(
        IMP::internal::create_tuple_restraint(bestn[i].second, m, vt));
    ret.back()->set_last_score(bestn[i].first);
  }
  return ret;
}

